from s114_course_common import teach
S='retinoscopy-intro'
teach(S,'l1',[
(0,'照進去，再看瞳孔裡的反光','客觀驗光是從光學反應估度數，不需要病人選哪片清楚。',[('Retinoscopy檢影','觀察眼底回光，配鏡片找中和'),('主觀驗光','受測者比較清楚與舒適，配合確認處方'),('用途','不易回答者尤其有幫助，也能發現異常反光線索')],'檢影不是單獨證明疾病或裝病的測驗；結果仍受調節與操作影響。'),
(2,'光帶是長條；掃動是你移動它的方向','水平的光帶，沿上下方向掃。',[('Streak光帶','投在眼上的長條光'),('觀察孔','檢查者從這裡看瞳孔內回光'),('套筒sleeve','調聚散與旋轉光帶；上下位置依機型確認')],'以下順逆動規則先以平面鏡效應說明，不能只背套筒一定朝某一邊。'),
(4,'調節：病人自己加了收光力量','眼睛用力對焦，可能讓檢影結果偏近視。',[('看遠方大目標','減少看近與辨認小字造成的調節'),('別遮住視線','避免病人改看近處檢查者'),('固定工作距離','選能穩定操作的距離，不是越遠就無條件越準')],'預放工作鏡是否需再扣，取決於記錄有沒有包含它；下一課分清毛值和剩餘讀值。')])
teach(S,'l2',[
(0,'檢查者坐得有限遠，要扣掉這個位置的影響','WD是距離，WL是距離換成的力量。',[('WD','working distance，眼到檢影鏡觀察位置，先用m'),('WL','working lens，1/WD，單位D'),('50cm','0.50m →WL＝+2.00D')],'67cm常近似1.50D；量測和紀錄要用同一個固定距離。'),
(2,'毛值包含工作鏡，淨值才是扣完之後','先問這個數字到底包含哪幾片鏡。',[('毛值Gross','全部中和鏡片力量，包含工作距離補償'),('淨值Rx','毛值−WL；毛值0、WL2 →−2D'),('預放WL另記','若讀值已排除那片WL，就不再扣一次')],'「有戴輔助鏡」本身不足以判斷是否要扣；關鍵是題目如何記讀值。'),
(4,'戴隱形眼鏡檢影：量的是還差多少','先算追加修正，再合成原鏡與修正。',[('Over-refraction','超額／追加驗光，鏡片戴著時還需加多少'),('先扣WL','若追加量是毛值，先變成淨追加量'),('再合成','低度數、同參考平面、球面鏡情境可近似相加')],'高度數或散光軸不同要處理頂點距離和方向，不能只把球面數字一加就算完整處方。')])
teach(S,'l3',[
(0,'順動和逆動，比的是回光與掃動','平面鏡效應下，順動加正、逆動加負，直到中和。',[('With順動','你往上掃，回光也往上'),('Against逆動','你往上掃，回光往下'),('Neutral中和','遠點到檢影鏡位置，瞳孔整片亮起')],'這裡看的是眼底回光，不是在平移一片眼鏡。'),
(2,'拿50cm工作距離做同一個例子','先找中和鏡，再扣+2D，別把順逆動直接當處方。',[('−3D才中和','毛值−3，淨值−3−2＝−5D'),('不加鏡就中和','毛值0，淨值0−2＝−2D'),('遠視／正視','未加鏡、調節放鬆的平面鏡效應下會順動')],'近視實遠點在檢查者內側會逆動；遠視是虛遠點，不能用未標方向的距離直接比大小。'),
(4,'平移鏡片看影像，是另一個任務','同叫順動，正在移的東西不同，不能混用口訣。',[('移動負鏡','物體的像跟鏡片同方向走'),('移動正鏡','像跟鏡片反方向走'),('純柱鏡','沿軸沒有柱鏡作用；垂直軸方向平移才看到該作用')],'檢影掃的是光；手動鏡片辨識移的是鏡。先說清對象再判正負。')])
teach(S,'l4',[
(0,'快、亮、寬：接近中和的樣子','這三個變化是在描述回光，不是病人視力的分數。',[('離中和遠','常較慢、暗、窄'),('接近中和','常較快、亮、寬'),('異常回光','扭曲或剪刀樣等需注意，不靠一種反光單獨確診')],'中央與周邊反應不同可受像差影響；剪刀樣也常與不規則散光有關，不能唯一歸因球面像差。'),
(2,'找主方向：先把投光和回光對齊','方向對齊後，還要分光帶方向與正在量的方向。',[('旋轉光帶','讓投光條和回光條平行，減少break或skew'),('沿垂直光帶方向掃','例如垂直光帶左右掃，測水平主方向的屈光'),('規則散光','再轉90°量另一個主方向')],'不要直接把光帶朝向抄成那次中和的屈光方向。'),
(4,'兩個方向各算完，再寫成一副處方','減WL改球面共同部分，不改兩方向差值。',[('光十字','每條方向記中和的毛值'),('兩條都減WL','變成淨值後比較'),('負散格式','較正者當S，另一值減S當C；軸沿S方向')],'每個方向扣一次同樣的WL；不是寫好S和C之後各自再減一次。')])
